-- calendar_mock seed
BEGIN;
-- 89 English business textoperationsEnglish business text；English business text、English business text、English business textreviewEnglish business text。
UPDATE events
SET event_id = REPLACE(event_id, 'evt_ops_', 'evt_ops_'),
    summary = CASE CAST(substr(event_id,-3) AS INTEGER) % 8
      WHEN 0 THEN 'English business textaccountEnglish business textanomalycash flowreview'
      WHEN 1 THEN 'brokerageholdings、English business textconcentrationreview'
      WHEN 2 THEN 'family membersauthorizationEnglish business textconflictEnglish business text'
      WHEN 3 THEN 'English business textaccounts receivableEnglish business textshort-term loanEnglish business text'
      WHEN 4 THEN 'core retail propertiesrentEnglish business texttaxes and feesEnglish business textreview'
      WHEN 5 THEN 'counselEnglish business textitem、disclosureEnglish business text'
      WHEN 6 THEN 'English business textitemEnglish business textaccountverify'
      ELSE 'succession、English business textmaterials preparation'
    END || ' · ' || substr(start_dt,1,10),
    description = CASE CAST(substr(event_id,-3) AS INTEGER) % 8
      WHEN 0 THEN 'operationsEnglish business textreconcileEnglish business textaccountEnglish business text、English business textstatus、pendingEnglish business textanomalyEnglish business text。'
      WHEN 1 THEN 'English business textreconcileholdingsEnglish business text、cashEnglish business text、English business textbufferEnglish business textriskEnglish business text。'
      WHEN 2 THEN 'English business textrecordverbal instruction、formalauthorization、related partyEnglish business textneedescalationEnglish business textconflict。'
      WHEN 3 THEN 'English business textupdateaccounts receivable、credit facilityreduction、collaterallistEnglish business textcashEnglish business text。'
      WHEN 4 THEN 'English business textreconcileEnglish business text、English business text、English business text、English business texttaxprepare。'
      WHEN 5 THEN 'English business textreconcileEnglish business textdisclosure、English business text、counselEnglish business textitemEnglish business text。'
      WHEN 6 THEN 'English business textreconcileEnglish business textstatus、English business text、English business text、English business textaccountEnglish business text。'
      ELSE 'successionEnglish business textreconcileEnglish business text、English business text、English business textcounselEnglish business textitem。'
    END,
    location = CASE CAST(substr(event_id,-3) AS INTEGER) % 4
      WHEN 0 THEN 'English business textfamily office·English business text'
      WHEN 1 THEN 'English business textfamily office·English business text'
      WHEN 2 THEN 'English business text'
      ELSE 'onlineEnglish business text'
    END
WHERE event_id LIKE 'evt_ops_%';
COMMIT;
